// ShareFile .
// @router /share/file/ [POST]
func ShareFile(ctx context.Context, c *app.RequestContext) {
	// 1. 解析表单参数（契约绑定 v0.6.1 起；此前手工 DefaultPostForm 逐一读取，
	//    password 更是契约外字段）
	var req sharemodel.ShareFileReq
	if err := c.BindAndValidate(&req); err != nil {
		c.JSON(consts.StatusBadRequest, map[string]interface{}{
			"code":    errcode.CodeInvalidParam,
			"message": err.Error(),
		})
		return
	}
	expireValue := int(req.ExpireValue)
	expireStyle := req.ExpireStyle
	requireAuth := req.RequireAuth
	password := ""
	if req.Password != nil {
		password = *req.Password
	}

	// 过期样式白名单
	if err := utils.CheckExpireStyleAllowed(expireStyle); err != nil {
		c.JSON(consts.StatusBadRequest, map[string]interface{}{
			"code":    errcode.CodeInvalidParam,
			"message": err.Error(),
		})
		return
	}

	// 2. 获取上传文件
	file, err := c.FormFile("file")
	if err != nil {
		c.JSON(consts.StatusBadRequest, map[string]interface{}{
			"code":    errcode.CodeInvalidParam,
			"message": "请上传文件",
		})
		return
	}

	// 3. 检查文件大小（upload.upload_size 单请求体上限，0=不限；
	// 修复：此前硬编码 10MB 不读配置，调大 upload_size 对直传通道无效）
	if maxSize := utils.GetMaxUploadSize(); maxSize > 0 && file.Size > maxSize {
		c.JSON(consts.StatusBadRequest, map[string]interface{}{
			"code":    errcode.CodeTooLarge,
			"message": fmt.Sprintf("文件大小超过限制（最大 %d MB）", maxSize/1024/1024),
		})
		return
	}

	// 3.5 上传闸门 + 匿名配额（治理回归：此前在 SaveFile 落盘之后才校验，
	// 被拒请求已把整文件写入存储——local 留孤儿、远端后端永久泄漏）
	{
		var gateUserID *uint
		if v, ok := middleware.UserIDFromContext(ctx); ok {
			gateUserID = &v
		}
		if err := gate.CheckUploadAllowed(gateUserID); err != nil {
			resp.NewTypedError(c, err)
			return
		}
		if err := gate.CheckUploadLogin(gateUserID); err != nil {
			resp.NewTypedError(c, err)
			return
		}
		if gateUserID == nil {
			if err := gate.CheckAnonymousQuota(ctx, middleware.ClientIP(c), file.Size); err != nil {
				resp.NewTypedError(c, err)
				return
			}
		}
	}

	// 4. 生成唯一文件名（原始文件名消毒后仅作展示存储，磁盘名用 UUID）
	originalFilename := utils.SanitizeFileName(file.Filename)

	// 4.5 内容安全校验：黑名单 + 白名单优先 + 魔数（修复：直传分享此前完全绕过
	// 扩展名检查，与 chunk/presign 通道防护不一致；魔数拦截"改扩展名"伪装）
	// E2E 密文分享跳过魔数复检（密文头是随机字节，必然不过魔数表）
	encryptedEarly := c.DefaultPostForm("encrypted", "false") == "true"
	var head []byte
	if !encryptedEarly {
		if f, err := file.Open(); err == nil {
			buf := make([]byte, 512)
			n, rerr := io.ReadFull(f, buf)
			if rerr == nil || rerr == io.ErrUnexpectedEOF {
				head = buf[:n]
			}
			_ = f.Close()
		}
		if err := utils.CheckUploadContent(originalFilename, head); err != nil {
			c.JSON(consts.StatusBadRequest, map[string]interface{}{
				"code":    errcode.CodeFileTypeDenied,
				"message": err.Error(),
			})
			return
		}
	}

	// 5+6. 落盘（磁盘布局与存储操作收口 app/share，HTTP 适配层不直连 storage）
	filePath, fileSize, fileHash, err := getShareService().SaveUploadFile(ctx, file, originalFilename)
	if err != nil {
		c.JSON(consts.StatusInternalServerError, map[string]interface{}{
			"code":    errcode.CodeInternal,
			"message": fmt.Sprintf("文件保存失败: %v", err),
		})
		return
	}

	// 7. 计算过期时间
	expireTime := utils.CalculateExpireTime(expireValue, expireStyle)
	expireCount := utils.CalculateExpireCount(expireStyle, expireValue)

	// 8. 获取用户ID（如果有）
	var userID *uint
	if uid, exists := c.Get("user_id"); exists {
		if uidUint, ok := uid.(uint); ok {
			userID = &uidUint
		}
	}

	// 9. 获取客户端 IP（可信代理解析）
	ownerIP := middleware.ClientIP(c)

	// 10. 确定上传类型
	uploadType := "anonymous"
	if userID != nil {
		uploadType = "authenticated"
	}

	// 10.5 密码保护:require_auth 时密码必填,bcrypt 哈希后入库(修复:此前 password
	// 被读取后直接丢弃,导致 PasswordHash 落库为空,取件侧空哈希校验形同虚设)
	passwordHash := ""
	if requireAuth {
		if password == "" {
			c.JSON(consts.StatusBadRequest, map[string]interface{}{
				"code":    errcode.CodeInvalidParam,
				"message": "开启密码保护时必须提供密码",
			})
			return
		}
		hash, err := utils.HashPassword(password)
		if err != nil {
			c.JSON(consts.StatusInternalServerError, map[string]interface{}{
				"code":    errcode.CodeInternal,
				"message": "密码处理失败",
			})
			return
		}
		passwordHash = hash
	}

	// 自定义取件码（P3）：仅登录用户可指定（防匿名抢注）
	customCode := ""
	if userID != nil {
		customCode = c.DefaultPostForm("custom_code", "")
	}

	// 文件备注（可空，取件页展示；2026-10-12 #489 文件+文本一并投递）
	note := ""
	if req.Note != nil {
		note = *req.Note
	}

	// 11. 构建分享请求（encrypted 于 4.5 处解析；E2E 密文分享）
	shareReq := &shareService.ShareFileReq{
		Channel:      "direct",
		FilePath:     filePath,
		Size:         fileSize,
		Text:         originalFilename, // 存储原始文件名
		ExpiredAt:    expireTime,
		ExpiredCount: expireCount,
		RequireAuth:  requireAuth,
		PasswordHash: passwordHash,
		UserID:       userID,
		UploadType:   uploadType,
		OwnerIP:      ownerIP,
		FileHash:     fileHash,
		Encrypted:    encryptedEarly,
		CustomCode:   customCode,
		Note:         note,
	}

	// 12. 调用 service 创建分享记录
	shareResult, err := getShareService().ShareFile(ctx, shareReq)
	if err != nil {
		resp.NewTypedError(c, err) // 配额/审核等 typed error 按业务码透传
		return
	}

	// 13. 构建响应：与 share service 同策略（publicShareURL——base_url 显式配置 >
	//     请求来源动态推断 > 相对路径）。此前经 PublicBaseURL 兜底静态拼
	//     server.host:port——监听地址 0.0.0.0 对外不可达（2026-10-07 fnOS 真机
	//     事故：文件分享响应给出 http://0.0.0.0:12345/... 链接）。
	fullShareURL := publicShareURL(ctx, shareResult.Code)

	// 传输日志（上传，异步）
	transfer.Record(transfer.Entry{
		Operation: transfer.OpUpload, FileCodeID: shareResult.ID, Code: shareResult.Code,
		FileName: originalFilename, FileSize: shareResult.Size,
		UserID: userID, APIKeyID: apiKeyIDPtr(ctx),
		Username: middleware.UsernameFromContext(ctx), IP: ownerIP,
	})

	message := "文件上传成功"
	var deduped *bool
	if shareResult.Deduped {
		message = "秒传成功（内容已存在，未重复占用存储）"
		deduped = boolPtr(true)
	}
	resp := &sharemodel.ShareFileResp{
		Code:    0,
		Message: message,
		Data: &sharemodel.ShareData{
			Code:       shareResult.Code,
			URL:        fullShareURL,
			PickupCode: strPtrIfNotEmpty(shareResult.PickupCode),
			Deduped:    deduped,
		},
	}

	c.JSON(consts.StatusOK, resp)
}

// GetShare .
// @router /share/select/ [GET]
func GetShare(ctx context.Context, c *app.RequestContext) {
	code := c.Query("code")
	// 取件密码经请求头（IDL share.thrift GetShareReq api.header 同步改；
	// query 形态有访问日志/Referer 泄漏面，2026-10-16 拍板与下载端点同批收敛）
	password := string(c.GetHeader("X-Share-Password"))

	if code == "" {
		c.JSON(consts.StatusBadRequest, map[string]interface{}{
			"code":    errcode.CodeInvalidParam,
			"message": "请提供分享码",
		})
		return
	}

	// 下载闸门：download.require_login（服务端 enforce，此前只透传前端）
	var pickupUserID *uint
	if v, ok := middleware.UserIDFromContext(ctx); ok {
		pickupUserID = &v
	}
	if err := gate.CheckDownloadLogin(pickupUserID); err != nil {
		resp.NewTypedError(c, err)
		return
	}

	// 取件内容（按码解析 → 规范分享码）。
	//
	// **先解析再预检锁定**：锁定键必须是**规范分享码**——6 位取件码与 8 位分享码
	// 指向同一条分享，锁定/失败记账统一在规范码上 ⇒ 同一把钥匙、爆破预算不翻倍。
	// 此前预检用原始入参、记账用规范码 ⇒ 6 位码入口的 429 预检**恒不命中**
	//（用户在 6 位码入口看不到预检触发的 429，只有深层闸门才拦）。
	fileCode, err := getShareService().GetFileByCode(ctx, code)
	if err != nil {
		var blocked *shareService.ShareBlockedError
		if errors.As(err, &blocked) {
			resp.NewTypedError(c, blocked)
			return
		}
		c.JSON(consts.StatusNotFound, map[string]interface{}{
			"code":    errcode.CodeNotFound,
			"message": "分享不存在或已过期",
		})
		return
	}

	// 失败锁定预检（防取件码/密码爆破；统一 scope "pickup"，与 download/
	// 匿名取件/preview 面共享 (IP, code) 失败计数）
	lock := middleware.GetDefaultLockout()
	lockKey := gate.PickupLockKey(middleware.ClientIP(c), fileCode.Code)
	if remain, locked := lock.CheckLocked(ctx, lockKey); locked {
		c.JSON(consts.StatusTooManyRequests, map[string]interface{}{
			"code":    errcode.CodeTooManyAttempts,
			"message": fmt.Sprintf("尝试过于频繁，已临时锁定，请 %d 秒后重试", remain),
		})
		return
	}

	// 占位分享（文件未上传）：与匿名通道同一业务码（20001）与文案 —— 此前此处
	// 返回 200 + 一条指向不存在文件的下载直链（点了就是 500）（2026-10-23 审计）。
	if shareService.IsShareNotReady(fileCode) {
		c.JSON(consts.StatusNotFound, map[string]interface{}{
			"code":    errcode.CodeShareNotFound,
			"message": "分享未完成上传，暂时无法取件",
		})
		return
	}

	// 取件次数已用完：给**明确**的业务码（20004 CodeShareReachLimit「超过取件
	// 次数」——该码位此前是保留未发射，正是为此预留），不再伪装成「不存在/已过期」。
	// 此前「次数耗尽」被 IsExpired 混作过期 ⇒ 404「分享不存在或已过期」。
	if fileCode.IsCountExhausted() {
		c.JSON(consts.StatusForbidden, map[string]interface{}{
			"code":    errcode.CodeShareReachLimit,
			"message": "超过取件次数",
		})
		return
	}

	// 密码保护校验（统一取件闸门 pkg/gate.CheckPickup；修复史:此处响应包含
	// 分享正文,空密码提示后必须真正校验密码,此前 TODO 未实现导致任意非空
	// 密码均可取到内容）
	if fileCode.RequireAuth {
		decision := gate.CheckPickup(ctx, gate.PickupState{
			RequireAuth:  true,
			PasswordHash: fileCode.PasswordHash,
		}, gate.PickupCheck{
			ClientIP: middleware.ClientIP(c),
			// 失败记账用**规范分享码**而不是用户原始入参：同一分享有两个入口
			// （8 位分享码 / 6 位取件码）⇒ 用原始码记账会变成**两把钥匙** ⇒
			// 密码爆破预算翻倍（2026-10-23 审计）。
			Code:     fileCode.Code,
			Password: password,
			// 本面历史规格：空密码是「需要密码」提示态，不记失败
			MissingCountsFailure: false,
		})
		switch decision.Verdict {
		case gate.PickupLocked:
			c.JSON(consts.StatusTooManyRequests, map[string]interface{}{
				"code":    errcode.CodeTooManyAttempts,
				"message": fmt.Sprintf("尝试过于频繁，已临时锁定，请 %d 秒后重试", decision.LockRemain),
			})
			return
		case gate.PickupPasswordMissing:
			// 密码门（缺密码）语义归 20003 分享密码门，不再用 401 字面量；
			// HTTP 层仍 401，data.has_password 供前端就地展开密码框
			c.JSON(consts.StatusUnauthorized, map[string]interface{}{
				"code":    errcode.CodeSharePasswordWrong,
				"message": "需要密码",
				"data": map[string]interface{}{
					"has_password": true,
				},
			})
			return
		case gate.PickupPasswordWrong:
			// 失败已由闸门在统一键记账（达到阈值触发锁定）
			c.JSON(consts.StatusUnauthorized, map[string]interface{}{
				"code":    errcode.CodeSharePasswordWrong,
				"message": "密码错误",
			})
			return
		}
	}
	// 校验通过，清空失败计数
	lock.Reset(ctx, lockKey)

	// 下发下载令牌（security.download_token.enabled 时 /share/download 必须携带）。
	// 令牌 = **一次取件的凭证**：下载时按令牌计次（同一令牌至多扣 1 次）。
	token := security.GenerateDownloadToken(fileCode.Code)

	// 直链走形态真相源（pkg/baseurl.ShareDownloadURL）：相对形态 + query 传码与令牌
	// （令牌必须在 query——落在 '#' 之后服务端收不到）。
	downloadURL := baseurl.ShareDownloadURL("", fileCode.Code, token)

	// 文本分享：正文在**本响应里交付** ⇒ 交付即取件 ⇒ 在交付前计次。
	// 此前文本分享在 select 即全文返回却**从不扣次、不记取件人、不写传输日志**
	// ⇒ owner 设的「按取件次数」上限对文本分享形同虚设（2026-10-24 审计）。
	// 计次键 = 本次签发的令牌指纹 ⇒ 随它下发的直链再被下载时**不再重复扣次**
	//（同一取件会话 = 一次取件）。
	if shareService.IsTextShare(fileCode) {
		if !chargePickup(ctx, c, fileCode.Code, security.DownloadTokenFingerprint(token),
			middleware.ClientIP(c), "select-text") {
			return
		}
		logTextView(ctx, fileCode, fileCode.Code, middleware.ClientIP(c))
	}

	// 契约响应（v0.6.0 起 ShareDetail 载全字段；此前为 ad-hoc map，
	// download_url/token/encrypted/is_multi/files 六个字段游窜契约外）
	data := &sharemodel.ShareDetail{
		Code:        fileCode.Code,
		Text:        fileCode.Text,
		FileName:    fileCode.UUIDFileName,
		FileSize:    fmt.Sprintf("%d", fileCode.Size),
		URL:         downloadURL,
		DownloadURL: &downloadURL,
		HasPassword: fileCode.RequireAuth,
		Encrypted:   &fileCode.Encrypted,
	}
	if token != "" {
		data.Token = &token
	}
	if fileCode.Note != "" {
		data.Note = &fileCode.Note
	}
	if fileCode.ExpiredAt != nil {
		data.ExpireTime = fileCode.ExpiredAt.Format("2006-01-02 15:04:05")
	}

	// 多文件列表（P0 多文件）：非文本分享附带 files 数组（含单文件，前端统一渲染）；
	// is_multi 标记文件数 >1（前端显示"打包下载"）。查询失败静默省略（不阻断取件）。
	if !shareService.IsTextShare(fileCode) {
		if items, lerr := getShareService().ListShareFiles(ctx, code); lerr == nil && len(items) > 0 {
			files := make([]*sharemodel.ShareFileItem, 0, len(items))
			for _, it := range items {
				files = append(files, &sharemodel.ShareFileItem{
					ID:   int64(it.ID),
					Name: it.Name,
					Size: it.Size,
				})
			}
			data.Files = files
			isMulti := len(items) > 1
			data.IsMulti = &isMulti
		}
	}

	c.JSON(consts.StatusOK, &sharemodel.GetShareResp{
		Code:    0,
		Message: "获取成功",
		Data:    data,
	})
}

// downloadTokenEnabled 是否强制下载令牌（security.download_token.enabled，默认 true）
func downloadTokenEnabled() bool {
	cfg := conf.GetGlobalConfig()
	if cfg == nil {
		return true
	}
	return cfg.Security.DownloadToken.Enabled
}

// s3DirectDownloadEnabled 是否开启 s3 直下（download.s3_direct_download，默认关）
func s3DirectDownloadEnabled() bool {
	cfg := conf.GetGlobalConfig()
	return cfg != nil && cfg.Download.S3DirectDownload
}

// authorizeDownload 下载链路公共鉴权段（DownloadFile / ZipDownload 共用）：
// 下载闸门 → 防爆破锁定 → 取件内容 → 下载令牌校验 → 密码校验。
//
// **不扣次、不记取件人**（2026-10-24）：扣次改到「内容交付前」执行
// （chargePickup，按取件会话/令牌计次）——此前扣次发生在鉴权段末尾，
// 早于子文件归属校验与 zip 组装 ⇒ 一次失败请求就白吃一次取件次数。
//
// 返回 (fileCode, tokenFingerprint, ok)：
//   - tokenFingerprint = 令牌的计次指纹（空 = 无有效令牌/令牌未启用 ⇒ 无会话概念，
//     按「每次交付算一次取件」处理）；
//   - 失败时已写入错误响应，调用方直接 return。
//
// password query 通道已移除（2026-10-16 拍板「一步到位」）：密码经
// URL query 有浏览器历史/访问日志/Referer 泄漏面，密码保护分享一律走取件流程
// （retrieve/getShare 以 POST body 校验密码后签发时间窗令牌）换凭证下载；
// 令牌未启用的部署对密码保护分享同样拒绝并明示原因。破坏性变更随 2.0.0 列车
// （pb CLI/MCP/前端均不消费该参数，已审计）。
func authorizeDownload(ctx context.Context, c *app.RequestContext, code, token string) (*model.FileCode, string, bool) {
	// 下载闸门：download.require_login（服务端 enforce）
	var dlUserID *uint
	if v, ok := middleware.UserIDFromContext(ctx); ok {
		dlUserID = &v
	}
	if err := gate.CheckDownloadLogin(dlUserID); err != nil {
		resp.NewTypedError(c, err)
		return nil, "", false
	}

	// 取件内容（按码解析 → 规范分享码）。
	//
	// **先解析再预检/验令牌**（2026-10-24）：
	// ① 锁定键用规范码 ⇒ 6 位取件码与 8 位分享码共享一把钥匙（预检与记账同键，
	//    此前预检用原始码 ⇒ 6 位码入口的 429 预检恒不命中）；
	// ② 令牌按**规范码**校验 ⇒ 用户把下载 URL 的 code 换成 6 位取件码也不再
	//    莫名 401「令牌无效」（此前签发按规范码、校验按原始码 ⇒ 形态不匹配）。
	fileCode, err := getShareService().GetFileByCode(ctx, code)
	if err != nil {
		var blocked *shareService.ShareBlockedError
		if errors.As(err, &blocked) {
			resp.NewTypedError(c, blocked)
			return nil, "", false
		}
		c.JSON(consts.StatusNotFound, map[string]interface{}{
			"code":    errcode.CodeNotFound,
			"message": "分享不存在或已过期",
		})
		return nil, "", false
	}

	// 失败锁定预检（防密码爆破；统一 scope "pickup"，与 select/匿名取件/
	// preview 面共享 (IP, code) 失败计数——此前独立 scope "download"）
	lock := middleware.GetDefaultLockout()
	lockKey := gate.PickupLockKey(middleware.ClientIP(c), fileCode.Code)
	if remain, locked := lock.CheckLocked(ctx, lockKey); locked {
		c.JSON(consts.StatusTooManyRequests, map[string]interface{}{
			"code":    errcode.CodeTooManyAttempts,
			"message": fmt.Sprintf("尝试过于频繁，已临时锁定，请 %d 秒后重试", remain),
		})
		return nil, "", false
	}

	// 下载令牌校验（security.download_token.enabled，默认开）：
	// 取件查询/匿名取件接口下发时间窗 HMAC 令牌，恒时比较校验。
	tokenEnabled := downloadTokenEnabled()
	fingerprint := ""
	tokenValid := false
	if tokenEnabled && token != "" {
		fingerprint = security.VerifyDownloadTokenFingerprint(fileCode.Code, token)
		tokenValid = fingerprint != ""
	}
	if !tokenValid {
		// 密码保护分享：无有效令牌一律拒绝（令牌未启用的部署也拦下并明示，
		// 不再提供 ?password= 旁路）
		if fileCode.RequireAuth {
			msg := "该分享受密码保护，请通过取件页获取下载凭证"
			if tokenEnabled && token != "" {
				msg = "下载令牌无效或已过期，请重新获取取件信息"
			} else if !tokenEnabled {
				msg = "该分享受密码保护，且下载令牌未启用，无法直接下载"
			}
			c.JSON(consts.StatusUnauthorized, map[string]interface{}{
				"code":    errcode.CodeDownloadToken,
				"message": msg,
			})
			return nil, "", false
		}
		if tokenEnabled {
			msg := "缺少下载令牌，请重新获取取件信息"
			if token != "" {
				msg = "下载令牌无效或已过期，请重新获取取件信息"
			}
			c.JSON(consts.StatusUnauthorized, map[string]interface{}{
				"code":    errcode.CodeDownloadToken,
				"message": msg,
			})
			return nil, "", false
		}
	}

	// 密码校验（持有效令牌视为已认证——令牌即等价已认证）。
	// ⚠️ 用**规范分享码**（fileCode.Code）查记录与记账：6 位取件码解析出的记录
	// 在 code 列是 8 位分享码 ⇒ 用原始码记账会命中 0 行 ⇒ 取件人/到件通知
	// 静默丢失（2026-10-23 审计）。
	viewerIP := middleware.ClientIP(c)
	if _, err := getShareService().GetFileWithUsage(ctx, fileCode.Code, "", viewerIP, tokenValid); err != nil {
		var blocked *shareService.ShareBlockedError
		if errors.As(err, &blocked) {
			resp.NewTypedError(c, blocked)
			return nil, "", false
		}
		var lockedErr *middleware.LockedError
		if errors.As(err, &lockedErr) {
			c.JSON(consts.StatusTooManyRequests, map[string]interface{}{
				"code":    errcode.CodeTooManyAttempts,
				"message": fmt.Sprintf("尝试过于频繁，已临时锁定，请 %d 秒后重试", lockedErr.RemainingSeconds),
			})
			return nil, "", false
		}
		if err.Error() == "密码错误" {
			// 失败已由域内统一闸门记账（达阈值触发锁定），此处不再重复计数
			c.JSON(consts.StatusUnauthorized, map[string]interface{}{
				"code":    errcode.CodeSharePasswordWrong,
				"message": "密码错误",
				"data": map[string]interface{}{
					"has_password": true,
				},
			})
			return nil, "", false
		}
		if errors.Is(err, shareService.ErrShareNotReady) {
			// 占位分享（文件未上传）与匿名通道同一业务码与文案（2026-10-23 审计：
			// 此前此处落泛化 404，而匿名通道是 20001 ⇒ 口径分叉）
			c.JSON(consts.StatusNotFound, map[string]interface{}{
				"code":    errcode.CodeShareNotFound,
				"message": err.Error(),
			})
			return nil, "", false
		}
		c.JSON(consts.StatusNotFound, map[string]interface{}{
			"code":    errcode.CodeNotFound,
			"message": "分享不存在或已过期",
		})
		return nil, "", false
	}
	lock.Reset(ctx, lockKey)

	return fileCode, fingerprint, true
}

// chargePickup 交付前计次（按取件会话/下载令牌）。
//
// 语义（2026-10-24）：**一个令牌至多扣 1 次取件次数** ——
//   - 多文件分享逐个下载 / 打包下载 / 断点续传 / 重复点击 ⇒ 同一次取件，只扣 1 次
//     （此前每个下载请求都扣 ⇒ 「取件次数=1 的多文件分享只能下载第一个文件」，
//     而打包 zip 又只扣 1 次 ⇒ 两条 UI 路径的次数语义不可比）；
//   - 记取件人也在此发生（同一取件只记一个取件人，不再每请求刷一次列表）。
//
// 返回 false 表示已写错误响应（次数已用完），调用方应立即返回、不再交付。
func chargePickup(ctx context.Context, c *app.RequestContext, code, fingerprint, viewerIP, channel string) bool {
	if fingerprint == "" {
		// 无令牌部署（security.download_token.enabled=false）：没有令牌 ⇒ 没有
		// 天然的「取件会话」凭证 ⇒ 用 (分享码, 取件人 IP) 兜底，否则多文件
		// 逐个下载会逐个扣次（关闭令牌时重现「次数=1 只能下载第一个文件」）。
		fingerprint = security.DownloadSessionKey(code, viewerIP)
	}
	charged, exhausted, err := getShareService().ChargePickup(ctx, code, fingerprint, channel)
	if err != nil {
		// 计次失败不阻断交付（与旧口径一致：记录错误但放行）——
		// DB 抖动不该让整个取件不可用。
		fmt.Printf("取件计次失败: %v\n", err)
		return true
	}
	if exhausted {
		// 20004「超过取件次数」（保留码位，此前未发射；前端 i18n 已备该文案）
		c.JSON(consts.StatusForbidden, map[string]interface{}{
			"code":    errcode.CodeShareReachLimit,
			"message": "超过取件次数",
		})
		return false
	}
	if charged {
		// 记取件人 + 通知 owner（fire-and-forget，GoSafe 兜底 panic 不影响进程）。
		async.GoSafe(func() {
			_ = getShareService().RecordViewerAndNotify(context.Background(), code, viewerIP, "")
		})
	}
	return true
}

// DownloadFile 下载分享文件
// @router /share/download [GET]
func DownloadFile(ctx context.Context, c *app.RequestContext) {
	code := c.Query("code")
	token := c.Query("token")

	if code == "" {
		c.JSON(consts.StatusBadRequest, map[string]interface{}{
			"code":    errcode.CodeInvalidParam,
			"message": "请提供分享码",
		})
		return
	}

	// 鉴权（不扣次）：解析规范码 → 锁定预检 → 令牌校验 → 密码校验。
	fileCode, fingerprint, ok := authorizeDownload(ctx, c, code, token)
	if !ok {
		return
	}
	viewerIP := middleware.ClientIP(c)

	// 如果是文本分享，直接返回文本（IsTextShare = Text 非空且无文件路径；
	// 文件分享的原始文件名也存在 Text 字段，不能仅凭 Text 判定——回归 P0）
	if shareService.IsTextShare(fileCode) {
		// 交付前计次（文本正文即交付内容；同一令牌不重复扣）
		if !chargePickup(ctx, c, fileCode.Code, fingerprint, viewerIP, "download-text") {
			return
		}
		c.Header("Content-Type", "text/plain; charset=utf-8")
		c.Header("Content-Disposition", `inline; filename="text.txt"`)
		c.SetBodyString(fileCode.Text)
		logTextView(ctx, fileCode, fileCode.Code, viewerIP)
		return
	}

	// 多文件分享下载入口（P0 多文件）：
	//   ?file=<子文件ID> → 单文件流；未指定且文件数 >1 → 直接流式 zip 打包
	var fileID uint
	if raw := c.Query("file"); raw != "" {
		if v, perr := strconv.ParseUint(raw, 10, 64); perr == nil {
			fileID = uint(v)
		}
	}
	if fileID > 0 {
		// 子文件归属校验**在扣次之前**：此前扣次在鉴权段末尾 ⇒ `file=` 不属于
		// 该分享时返回 404，但取件次数已被吃掉（白扔一次取件机会）。
		fc, child, gerr := getShareService().GetShareChild(ctx, fileCode.Code, fileID)
		if gerr != nil || fc == nil || child == nil {
			c.JSON(consts.StatusNotFound, map[string]interface{}{
				"code":    errcode.CodeNotFound,
				"message": "文件不存在或不属于该分享",
			})
			return
		}
		// 计次（按取件会话）：多文件逐个下载 ⇒ 同一令牌只扣 1 次。
		if !chargePickup(ctx, c, fileCode.Code, fingerprint, viewerIP, "download") {
			return
		}
		streamChildFile(ctx, c, fc, child, viewerIP)
		return
	}
	// 用**规范码**列子文件（此前用原始入参 ⇒ 6 位取件码入口解析不到子文件表
	// ⇒ 多文件分享退化成单文件分支 → 文件路径为空 → 500）。
	if items, lerr := getShareService().ListShareFiles(ctx, fileCode.Code); lerr == nil && len(items) > 1 {
		// 多文件：流式 zip 打包（不 302，避免浏览器二次请求丢失鉴权参数）。
		// 组装失败**在扣次之前**返回 500（不白吃一次取件次数）。
		rc, zerr := getShareService().ZipStream(ctx, fileCode)
		if zerr != nil {
			c.JSON(consts.StatusInternalServerError, map[string]interface{}{
				"code":    errcode.CodeInternal,
				"message": "打包下载失败",
			})
			return
		}
		if !chargePickup(ctx, c, fileCode.Code, fingerprint, viewerIP, "download") {
			return
		}
		writeShareZip(ctx, c, fileCode, rc, viewerIP)
		return
	}

	// 如果是文件分享，流式返回文件
	filePath := fileCode.GetFilePath()
	if filePath == "" {
		c.JSON(consts.StatusInternalServerError, map[string]interface{}{
			"code":    errcode.CodeInternal,
			"message": "文件路径为空",
		})
		return
	}

	// 计次（按取件会话）：断点续传 / 重复点击 ⇒ 同一令牌只扣 1 次。
	if !chargePickup(ctx, c, fileCode.Code, fingerprint, viewerIP, "download") {
		return
	}

	// 传输日志（异步，fire-and-forget）：此前 transfer_log 表无任何写入方，
	// 传输日志页与趋势下载序列一直空数据。文本分享按查看计，文件按下载计。
	logTransfer := func() {
		logName := fileCode.UUIDFileName
		if logName == "" {
			logName = fileCode.Text // 直传分享未落 UUIDFileName，Text 存的是原始文件名
		}
		if shareService.IsTextShare(fileCode) {
			logName = "text.txt"
		}
		var logUser *uint
		logUsername := ""
		if uid, ok := middleware.UserIDFromContext(ctx); ok {
			logUser = &uid
		}
		if n := middleware.UsernameFromContext(ctx); n != "" {
			logUsername = n
		}
		transfer.Record(transfer.Entry{
			Operation: transfer.OpDownload, FileCodeID: fileCode.ID, Code: code,
			FileName: logName, FileSize: fileCode.Size,
			UserID: logUser, APIKeyID: apiKeyIDPtr(ctx),
			Username: logUsername, IP: viewerIP,
		})
	}

	// 呈现文件名（s3 直下 302 的 response-content-disposition 与下方中转流共用）
	fileName := fileCode.DisplayName()

	// s3 直下（可选开关 download.s3_direct_download，默认关）：当前后端支持
	// 真预签名时 302 到短时效预签名 GET，下载流量不经过服务器。
	// 访问校验/密码/次数扣减均已在上方完成；不支持或签发失败则回退服务端中转。
	if s3DirectDownloadEnabled() {
		if u, perr := getShareService().PresignDownloadURL(ctx, filePath, 10*time.Minute, fileName); perr == nil {
			logTransfer()
			c.Header("Cache-Control", "no-store")
			c.Redirect(consts.StatusFound, []byte(u))
			return
		}
	}

	// 统一下传送流：本地后端 c.File 原生 Range/断点续传；远端后端服务端
	// 区间流（206，驱动支持时），不支持区间读的驱动回退全量 200。
	// 惰性开流：Range 请求只做 Stat+区间 GET，不预开全量读器。
	streamFileDownload(ctx, c, filePath, fileName, logTransfer)
}

// closeOnEOFReader 包装 ReadCloser：读至 EOF 时自动 Close。
// 用于 Hertz 延迟流式写出的场景（handler 返回后才开始读 body）。
type closeOnEOFReader struct {
	rc io.ReadCloser
}

func (w *closeOnEOFReader) Read(p []byte) (int, error) {
	n, err := w.rc.Read(p)
	if err != nil {
		// EOF 与传输中断（客户端断开等）都要释放底层连接：
		// 只在 EOF 关闭会让中断的下载把连接池占到 GC。
		_ = w.rc.Close()
	}
	return n, err
}

func newCloseOnEOFReader(rc io.ReadCloser) io.Reader {
	return &closeOnEOFReader{rc: rc}
}

// apiKeyIDPtr 提取 ctx 中的 API Key 归因（JWT/匿名请求返回 nil）。
func apiKeyIDPtr(ctx context.Context) *uint {
	if id, ok := middleware.APIKeyIDFromContext(ctx); ok {
		return &id
	}
	return nil
}

// logTextView 文本分享的取件日志（2026-10-24）。
//
// 此前文本分享的正文在 /share/select 即交付，而传输日志只在 /share/download
// 的**文件**分支写 ⇒ 文本分享的取件在传输日志里完全失明（owner 看不到谁读了文本）。
func logTextView(ctx context.Context, fc *model.FileCode, code, viewerIP string) {
	var logUser *uint
	if uid, ok := middleware.UserIDFromContext(ctx); ok {
		logUser = &uid
	}
	transfer.Record(transfer.Entry{
		Operation: transfer.OpDownload, FileCodeID: fc.ID, Code: code,
		FileName: "text.txt", FileSize: fc.Size,
		UserID: logUser, APIKeyID: apiKeyIDPtr(ctx),
		Username: middleware.UsernameFromContext(ctx), IP: viewerIP,
	})
}

// ==================== 用户分享管理（2026-10-09 自 customHandler/share_user.go 收敛进 IDL） ====================
// 契约真相源：idl/share.thrift UserShares*（wire 形态与手写契约时代逐字段兼容）。
// 认证保持原 requireLogin 语义（全局身份中间件注入 user_id，未登录 401 JSON），
// 不上移到路由中间件，保证迁移前后行为一致。
// ⚠️ 本文件手工区：scripts/gen-router.sh 的去噪循环只摘 hzmodel import 行，
// 但手工实现务必随列车提交——未提交状态跑旧版脚本会被整文件回退。

// requireUserID 提取登录用户 ID；未登录写 401 响应并返回 false
func requireUserID(c *app.RequestContext) (uint, bool) {
	if v, ok := c.Get("user_id"); ok {
		if id, ok := v.(uint); ok {
			return id, true
		}
	}
	c.JSON(consts.StatusUnauthorized, map[string]interface{}{"code": errcode.CodeUnauthorized, "message": "未登录"})
	return 0, false
}

// UserSharesList 我的分享列表
// GET /api/v1/user/shares?status=&search=&page=&page_size=
func UserSharesList(ctx context.Context, c *app.RequestContext) {
	uid, ok := requireUserID(c)
	if !ok {
		return
	}

	page, _ := strconv.Atoi(string(c.Query("page")))
	pageSize, _ := strconv.Atoi(string(c.Query("page_size")))

	items, total, err := getShareService().ListUserShares(ctx, uid,
		string(c.Query("status")), string(c.Query("search")), page, pageSize)
	if err != nil {
		c.JSON(consts.StatusInternalServerError, map[string]interface{}{
			"code": errcode.CodeInternal, "message": "获取分享列表失败: " + err.Error(),
		})
		return
	}

	if page < 1 {
		page = 1
	}
	if pageSize < 1 {
		pageSize = 20
	}
	totalPages := (total + int64(pageSize) - 1) / int64(pageSize)
	if totalPages < 1 {
		totalPages = 1
	}

	c.JSON(consts.StatusOK, &sharemodel.UserSharesListResp{
		Code:    0,
		Message: "ok",
		Data: &sharemodel.UserSharesListData{
			Items:      items,
			Total:      total,
			Page:       int32(page),
			PageSize:   int32(pageSize),
			TotalPages: totalPages,
			HasNext:    int64(page) < totalPages,
			HasPrev:    int64(page) > 1,
		},
	})
}

// UserSharesBatchDelete 批量软删除我的分享
// POST /api/v1/user/shares/batch-delete
func UserSharesBatchDelete(ctx context.Context, c *app.RequestContext) {
	uid, ok := requireUserID(c)
	if !ok {
		return
	}
	var req sharemodel.UserShareCodesReq
	if err := c.BindAndValidate(&req); err != nil {
		c.JSON(consts.StatusBadRequest, map[string]interface{}{"code": errcode.CodeInvalidParam, "message": err.Error()})
		return
	}
	if len(req.Codes) == 0 {
		c.JSON(consts.StatusBadRequest, map[string]interface{}{"code": errcode.CodeInvalidParam, "message": "codes 不能为空"})
		return
	}
	n, err := getShareService().BatchDeleteUserShares(ctx, uid, req.Codes)
	if err != nil {
		c.JSON(consts.StatusInternalServerError, map[string]interface{}{"code": errcode.CodeInternal, "message": "删除失败: " + err.Error()})
		return
	}
	c.JSON(consts.StatusOK, &sharemodel.UserShareOpResp{
		Code:    0,
		Message: "ok",
		Data:    map[string]int32{"deleted": int32(n)},
	})
}

// UserSharesBatchExtend 批量延期我的分享
// POST /api/v1/user/shares/batch-extend
func UserSharesBatchExtend(ctx context.Context, c *app.RequestContext) {
	uid, ok := requireUserID(c)
	if !ok {
		return
	}
	var req sharemodel.UserShareBatchExtendReq
	if err := c.BindAndValidate(&req); err != nil {
		c.JSON(consts.StatusBadRequest, map[string]interface{}{"code": errcode.CodeInvalidParam, "message": err.Error()})
		return
	}
	if len(req.Codes) == 0 {
		c.JSON(consts.StatusBadRequest, map[string]interface{}{"code": errcode.CodeInvalidParam, "message": "codes 不能为空"})
		return
	}
	var newExpire *time.Time
	if req.Forever != nil && *req.Forever {
		// nil 表示永久（清空 expired_at 字段）
		newExpire = nil
	} else if req.Hours != nil && *req.Hours > 0 {
		t := time.Now().Add(time.Duration(*req.Hours) * time.Hour)
		newExpire = &t
	} else {
		c.JSON(consts.StatusBadRequest, map[string]interface{}{"code": errcode.CodeInvalidParam, "message": "hours 必须 > 0 或 forever=true"})
		return
	}
	n, err := getShareService().BatchExtendUserShares(ctx, uid, req.Codes, newExpire)
	if err != nil {
		c.JSON(consts.StatusInternalServerError, map[string]interface{}{"code": errcode.CodeInternal, "message": "延期失败: " + err.Error()})
		return
	}
	c.JSON(consts.StatusOK, &sharemodel.UserShareOpResp{
		Code:    0,
		Message: "ok",
		Data:    map[string]int32{"extended": int32(n)},
	})
}

// UserSharesRestore 恢复软删除的分享
// POST /api/v1/user/shares/:code/restore
func UserSharesRestore(ctx context.Context, c *app.RequestContext) {
	uid, ok := requireUserID(c)
	if !ok {
		return
	}
	var req sharemodel.UserShareCodeReq
	if err := c.BindAndValidate(&req); err != nil {
		c.JSON(consts.StatusBadRequest, map[string]interface{}{"code": errcode.CodeInvalidParam, "message": err.Error()})
		return
	}
	if req.Code == "" {
		c.JSON(consts.StatusBadRequest, map[string]interface{}{"code": errcode.CodeInvalidParam, "message": "code 必填"})
		return
	}
	if err := getShareService().RestoreUserShare(ctx, uid, req.Code); err != nil {
		// 不在回收站（已硬删/不存在/本就活跃）：显式 400，替代 200 静默 no-op
		if errors.Is(err, shareService.ErrNotInRecycleBin) {
			c.JSON(consts.StatusBadRequest, map[string]interface{}{"code": errcode.CodeInvalidParam, "message": err.Error()})
			return
		}
		c.JSON(consts.StatusInternalServerError, map[string]interface{}{"code": errcode.CodeInternal, "message": "恢复失败: " + err.Error()})
		return
	}
	c.JSON(consts.StatusOK, &sharemodel.UserShareOpResp{Code: 0, Message: "ok"})
}

// UserSharesHardDelete 永久删除（仅已软删除的）
// DELETE /api/v1/user/shares/:code/hard
func UserSharesHardDelete(ctx context.Context, c *app.RequestContext) {
	uid, ok := requireUserID(c)
	if !ok {
		return
	}
	var req sharemodel.UserShareCodeReq
	if err := c.BindAndValidate(&req); err != nil {
		c.JSON(consts.StatusBadRequest, map[string]interface{}{"code": errcode.CodeInvalidParam, "message": err.Error()})
		return
	}
	if req.Code == "" {
		c.JSON(consts.StatusBadRequest, map[string]interface{}{"code": errcode.CodeInvalidParam, "message": "code 必填"})
		return
	}
	if err := getShareService().HardDeleteUserShare(ctx, uid, req.Code); err != nil {
		// 不在回收站（未软删/不存在）：显式 400，替代 200 静默 no-op
		if errors.Is(err, shareService.ErrNotInRecycleBin) {
			c.JSON(consts.StatusBadRequest, map[string]interface{}{"code": errcode.CodeInvalidParam, "message": err.Error()})
			return
		}
		c.JSON(consts.StatusInternalServerError, map[string]interface{}{"code": errcode.CodeInternal, "message": "永久删除失败: " + err.Error()})
		return
	}
	c.JSON(consts.StatusOK, &sharemodel.UserShareOpResp{Code: 0, Message: "ok"})
}
